#!/bin/sh
# Starts smbd for SMB_ROLE (office|cnc) from files generated by cnc-admin:
#   /etc/cnc/smb-<role>.conf     Samba configuration
#   /etc/cnc/<role>-users.txt    "<username> <NT hash>" per line
set -eu

: "${SMB_ROLE:?SMB_ROLE must be office or cnc}"
: "${CNC_UID:?}" "${CNC_GID:?}"

conf="/etc/cnc/smb-${SMB_ROLE}.conf"
users="/etc/cnc/${SMB_ROLE}-users.txt"
for f in "$conf" "$users"; do
    [ -f "$f" ] || { echo "Missing $f (run: docker compose run --rm cnc-admin python -m cncadmin.cli init)" >&2; exit 1; }
done
cp "$conf" /etc/samba/smb.conf

# All files are owned by one account so both Samba instances and File Browser agree.
getent group cncfiles >/dev/null || groupadd -g "$CNC_GID" cncfiles
getent passwd cncfiles >/dev/null || useradd -M -N -u "$CNC_UID" -g cncfiles -s /usr/sbin/nologin cncfiles

# "docker restart" keeps the container filesystem: drop users from the previous run
# so removed machines/users really lose access.
for u in $(awk -F: '$5 == "cnc-managed" { print $1 }' /etc/passwd); do
    userdel "$u"
done
rm -f /var/lib/samba/private/passdb.tdb

grep -v '^[[:space:]]*\(#\|$\)' "$users" | while read -r user hash; do
    # A bad entry must not take the whole file server down: skip it and log why.
    if ! useradd -M -N -g cncfiles -c cnc-managed -s /usr/sbin/nologin "$user"; then
        echo "WARNING: could not create user '$user'; skipped" >&2
        continue
    fi
    tmp=$(head -c 18 /dev/urandom | base64)
    printf '%s\n%s\n' "$tmp" "$tmp" | pdbedit -a -t -u "$user" >/dev/null
    pdbedit -u "$user" --set-nt-hash="$hash" >/dev/null
    echo "Samba user ready: $user"
done

testparm -s /etc/samba/smb.conf >/dev/null

if [ "$SMB_ROLE" = cnc ] && [ "${ENABLE_NMBD:-no}" = yes ]; then
    nmbd --daemon
fi

exec smbd --foreground --no-process-group --debug-stdout
